gabT(){return"\u041a\u0430\u043a \u044d\u0442\u043e \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442"},
gadQ(){return"\u041f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u044c"},
