gadN(){return"\u0412\u0432\u043e\u0434 \u0437\u0430 2 \u0441\u0435\u043a\u0443\u043d\u0434\u044b"},
gadM(){return"\u041d\u0430\u0447\u043d\u0438\u0442\u0435 \u043f\u0435\u0447\u0430\u0442\u0430\u0442\u044c \u2014 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438 \u0441\u0430\u043c\u0438 \u043f\u043e\u0434\u0441\u0442\u0430\u0432\u044f\u0442 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044e \u0438 \u0438\u043a\u043e\u043d\u043a\u0443. \u041c\u043e\u0436\u043d\u043e \u0433\u043e\u043b\u043e\u0441\u043e\u043c, \u0444\u043e\u0442\u043e, \u043f\u043e \u0448\u0442\u0440\u0438\u0445-\u043a\u043e\u0434\u0443. \u0417\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u0435 \u043a\u0430\u0442\u0430\u043b\u043e\u0433\u0438 Mercadona \u0438 Lidl \u2014 \u0431\u0443\u0434\u0443\u0442 \u0446\u0435\u043d\u044b \u0438 \u0444\u043e\u0442\u043e \u0442\u043e\u0432\u0430\u0440\u043e\u0432."},
gadP(){return"\u0421\u043f\u0438\u0441\u043a\u0438 \u043d\u0430 \u0434\u0432\u043e\u0438\u0445"},
gadO(){return"\u041f\u043e\u0434\u0435\u043b\u0438\u0442\u0435\u0441\u044c \u0441\u043f\u0438\u0441\u043a\u043e\u043c 6-\u0437\u043d\u0430\u0447\u043d\u044b\u043c \u043a\u043e\u0434\u043e\u043c \u2014 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043c\u0433\u043d\u043e\u0432\u0435\u043d\u043d\u043e. \u0412\u0438\u0434\u043d\u043e, \u043a\u0442\u043e \u0441\u0435\u0439\u0447\u0430\u0441 \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u0441\u043f\u0438\u0441\u043e\u043a \u0438 \u043a\u0442\u043e \u0447\u0442\u043e \u043a\u0443\u043f\u0438\u043b. \u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u044c\u0442\u0435\u0441\u044c, \u0447\u0442\u043e\u0431\u044b \u0432\u0430\u0441 \u0443\u0437\u043d\u0430\u0432\u0430\u043b\u0438:"},
ga8V(){return"\u041f\u043e\u043d\u044f\u0442\u043d\u043e"},
ga8X(){return"\u0421\u043e\u0437\u0434\u0430\u0439\u0442\u0435 \u0441\u043f\u0438\u0441\u043e\u043a \u043a\u043d\u043e\u043f\u043a\u043e\u0439 \xab+\xbb. \u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0442\u0438\u043f \u2014 \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u044b, \u0430\u043f\u0442\u0435\u043a\u0430, \u0445\u043e\u0437\u044f\u0439\u0441\u0442\u0432\u043e\u2026 \u2014 \u0443 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0432\u043e\u0438 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0438 \u0438 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438."},
